#include <stdio.h>
#include <string.h>

int main(void)
{
    char room[] = "Lab-204";
    char *suffix = strchr(room, '-');
    if (suffix != NULL) {
        suffix++;
        suffix[0] = '3';
        printf("%s %s\n", room, suffix);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void)
{
    const char *text = "CSE212";
    size_t count = 0;
    for (const char *p = text; *p != '\0'; p++) {
        count++;
    }
    printf("%zu %zu\n", count, strlen(text + 3));
    return 0;
}

examQuestions.question:
What lengths does the full walk and the offset strlen produce?

#include <stdio.h>
#include <string.h>

int main(void)
{
    const char *text = "CSE212";
    size_t count = 0;
    for (const char *p = text; *p != '\0'; p++) {
        count++;
    }
    printf("%zu %zu\n", count, strlen(text + 3));
    return 0;
}
